import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`actor-website-audit`,heroTitle:`Audit your actor website in minutes`,heroSubtitle:`Perplexity Computer reviews your actor website, reel presentation, credits, and booking flow, then shows what to fix to look more castable.`,inputUrlCta:`Audit my site`,inputUrlPlaceholder:`youractorsite.com`,inputUrlPrefill:`Go to {url} and run a full actor website audit. 1) Review the homepage, headshots, reel placement, resume or credits, bio, contact flow, mobile experience, and social links. 2) Analyze whether the site quickly communicates casting type, range, recent work, and how to book or contact the actor. 3) Benchmark against strong actor websites and agency profiles for presentation, proof, and clarity. 4) Recommend the highest-impact fixes for casting directors, agents, and managers. 5) Deliver a prioritized action plan with rewritten copy, content suggestions, and booking-flow improvements.`,heroOverlaySteps:[`Reviewing headshots, reel placement, credits, bio, contact flow, and mobile UX`,`Benchmarking strong actor sites and profiles for clarity and proof`,`Finding the updates most likely to improve casting and representation signals`,`Website audit, copy fixes, and content plan ready to use`],generatingSteps:[`Visiting {url} to review your actor site, reel, credits, and contact flow`,`Designing an agent to benchmark strong actor websites and industry profiles`,`Configuring copy rewrites, content recommendations, and booking-flow fixes`,`Packaging the work into a prioritized site improvement plan`],featureSectionTitle:`From portfolio gaps to a stronger casting signal`,featureCardTitles:[`Connects to your actor toolkit`,`Updates you can make next`],featureCardDescriptions:[`Computer breaks your actor site audit into portfolio review, reel analysis, industry benchmarking, and copy improvements, then routes each step to the right model.`,`Your website, reel links, resumes, social profiles, Docs, and Sheets can feed one workflow so the audit reflects your full presence.`,`Homepage rewrites. Reel-placement fixes. Credit and bio updates. Contact-flow improvements. Computer gives you the changes most likely to sharpen your first impression.`],capabilitySectionTitle:`Your actor website strategist, on demand`,capabilitySectionSubtitle:`Paste your site, step away, and come back to a sharper plan for casting-ready presentation.`,capabilityCards:[{title:`Portfolio Audit`,description:`Computer can review headshots, reels, credits, bio, and contact flow to find presentation gaps.`},{title:`Industry Benchmarking`,description:`Computer can compare your site with strong actor websites and agency profiles to surface clearer positioning.`},{title:`Copy and Content Fixes`,description:`Computer can rewrite your bio, homepage copy, and CTA language while suggesting missing content.`},{title:`Connect Your Tools`,description:`Computer can organize findings across your site, reel links, resume files, social profiles, Docs, and Sheets.`},{title:`Remember Your Brand`,description:`Computer can remember your casting type, credits, and goals so future updates stay aligned.`},{title:`Refresh the Audit`,description:`Computer can revisit your site after new credits, reels, or photos and recommend the next round of improvements.`}]});export{t as default};
